fields.InputDefinition:
{
  "goal": "Open the 'Members' entity via the LEFT sidebar 'Search record types...' box (type 'Members', click the exact match), click a member row, then click 'Open Full Record' to load the full form. This shared setup is done ONCE. Then exercise these form controls IN ORDER, and as you finish each set \"checkpointReached\" to the exact checkpoint name shown: The section and layout controls live in the toolbar's 'View' panel (the 'View' button at the TOP-RIGHT of the toolbar, sliders icon): open it before each control below, and reopen it if it has closed. (1) section-search — in the View panel's 'Search sections...' input, type a term matching a visible section heading and confirm the sections narrow to matches, then type gibberish (e.g. 'zzzqqq') and confirm a 'No sections found' empty state with a 'Clear search' action; (2) expand-collapse-all — in the View panel click 'Collapse all' (tooltip 'Collapse all sections') and confirm sections collapse to headers, then reopen View and click 'Expand all' (tooltip 'Expand all sections') and confirm the bodies re-open; (3) width-toggle — in the View panel click 'Use full width' (or 'Center content' when already full width) and confirm the form content layout width visibly changes; (4) section-manager — in the View panel click 'Reorder sections' (bars-staggered icon) and confirm the 'Manage Sections' drawer opens listing sections with up/down arrows and a 'Reset to Default Order' option; (5) section-collapse-toggle — click a single section's header (or its chevron) and confirm ONLY that section collapses, then click it again and confirm it re-expands. Keep going until every control has been exercised. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 65,
  "checkpoints": [
    {
      "name": "section-search",
      "instruction": "section search-filter narrows and shows no-match empty state",
      "visualCriteria": [
        "Typing a matching term in the View panel's 'Search sections...' box narrows the visible sections to matches, and typing a non-matching term shows a 'No sections found' empty state with a Clear search option"
      ]
    },
    {
      "name": "expand-collapse-all",
      "instruction": "bulk collapse-all then expand-all",
      "visualCriteria": [
        "Clicking 'Collapse all' in the View panel collapses the form's section panels to their headers, and clicking 'Expand all' re-expands the section bodies"
      ]
    },
    {
      "name": "width-toggle",
      "instruction": "form width toggle changes content width",
      "visualCriteria": [
        "Clicking the View panel's width toggle (Use full width / Center content) visibly changes the form content layout width — the panels widen to full-width or re-center"
      ]
    },
    {
      "name": "section-manager",
      "instruction": "Manage Sections drawer opens with reorder controls",
      "visualCriteria": [
        "Clicking 'Reorder sections' in the View panel opens a 'Manage Sections' drawer listing the form's sections with up/down move buttons and a 'Reset to Default Order' option"
      ]
    },
    {
      "name": "section-collapse-toggle",
      "instruction": "single section header toggles just that section",
      "visualCriteria": [
        "Clicking a single section's header collapses just that section's body (chevron flips), and clicking it again re-expands only that section"
      ]
    }
  ]
}
